const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const windhoek = ee.Geometry.Point([17.0832, -22.5700]); // Windhoek coordinates
  const roi = windhoek.buffer(10000); // 10km buffer around Windhoek

  const date2020 = '2020-01-29';
  const date2021 = '2021-02-07';

  // 2. Data Acquisition - Sentinel-2
  function getS2Image(date) {
    const startDate = ee.Date(date);
    const endDate = startDate.advance(1, 'day');

    let collection = ee.ImageCollection('COPERNICUS/S2_SR')
      .filterBounds(roi)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

    // Cloud masking function
    function maskS2clouds(image) {
      const qa = image.select('QA60');
      const cloudBitMask = 1 << 10;
      const cirrusBitMask = 1 << 11;
      const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                   .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
      return image.updateMask(mask);
    }

    collection = collection.map(maskS2clouds);

    if (collection.size().getInfo() > 0) {
      return collection.median().clip(roi);
    }
    return null;
  }

  // 3. Get images for both dates
  const img2020 = getS2Image(date2020);
  const img2021 = getS2Image(date2021);

  // Check if collections are empty
  if (!img2020 || !img2021) {
    console.log("2020 Images: 0");
    console.log("2021 Images: 0");
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Calculate NDVI for both images
  function calculateNDVI(image) {
    return image.normalizedDifference(['B8', 'B4']).rename('NDVI');
  }

  const ndvi2020 = calculateNDVI(img2020);
  const ndvi2021 = calculateNDVI(img2021);

  // 5. Compute statistics
  const stats2020 = ndvi2020.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2021 = ndvi2021.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  });

  const mean2020 = stats2020.get('NDVI').getInfo();
  const count2020 = stats2020.get('NDVI_count').getInfo();
  const mean2021 = stats2021.get('NDVI').getInfo();
  const count2021 = stats2021.get('NDVI_count').getInfo();

  // 6. Validation checks
  console.log(`2020-01-29: Mean NDVI ${mean2020?.toFixed(3)}, Pixels: ${count2020}`);
  console.log(`2021-02-07: Mean NDVI ${mean2021?.toFixed(3)}, Pixels: ${count2021}`);

  if (count2020 === 0 || count2021 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (mean2020 === null || mean2021 === null || 
      isNaN(mean2020) || isNaN(mean2021) ||
      mean2020 > 1 || mean2020 < -1 || 
      mean2021 > 1 || mean2021 < -1) {
    console.log("<answer>C3</answer>");
    return;
  }

  // 7. Final comparison
  if (mean2021 > mean2020) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
